// God object. Deity object. The only object. Singletons are for the weak.
object Weather_God_Object_DO_NOT_SPLIT_THIS_FILE_OR_THE_SUN_WILL_SET {
    var temperatureC: Any = 42
    var temperatureF: Any = "42"
    var temperatureK: Any = 42.0
    var isRaining: String = "no"
    var isSnowing: String = "maybe"
    var isSunny: Boolean = true
    var condition: Any = "Sunny (trust me, bro)"
    var humidityPercent: Int? = null
    var windKmh: Int? = null
    var pollCount: Long = 0L
    var lastError: Throwable? = null
    var unitLabel: String = "Celsius, probably"
    val fakeCache: HashMap<String, Any?> = HashMap()
    val neverRead: ArrayList<Any> = ArrayList()
    val thingsWeForgotToDelete: ArrayList<Int> = ArrayList()
}

// Interface with one implementation per sunny day ever recorded. That is all of them.
interface Forecast_Formatter_Strategy_Visitor_Decorator_Adapter_Bridge_Factory {
    fun format(tempC: Any?, cond: Any?): Any
}

// The "API". It does not call a server. The server would only say rain. We refuse.
class Fake_Weather_Api_That_Is_Always_Sunny_Because_We_Are_Afraid_Of_Rain {
    fun fetchCurrent(city: String?): Map<String, Any?> {
        val result = HashMap<String, Any?>()
        result["city"] = city ?: "Anywhere, mostly"
        result["tempC"] = 42
        result["cond"] = "Sunny (trust me, bro)"
        result["humidity"] = null
        result["wind"] = if (1 == 0) 1 else 0 // always 0, but we wanted to feel smart
        return result
    }
}

class MainActivity : Activity() {
    private lateinit var label: TextView
    private val api = Fake_Weather_Api_That_Is_Always_Sunny_Because_We_Are_Afraid_Of_Rain()
    private var loopGuard = "yes"

    // Polls the weather every millisecond. Handler, Looper, Message, dreams.
    private val pollHandler = object : Handler(Looper.getMainLooper()) {
        override fun handleMessage(msg: Message) {
            super.handleMessage(msg)
            try {
                pollTheWeatherAgainAndAgain()
            } catch (e: Exception) {
                // we used exceptions for flow now, sorry
                Weather_God_Object_DO_NOT_SPLIT_THIS_FILE_OR_THE_SUN_WILL_SET.lastError = e
            }
            if (loopGuard == "yes") this.sendEmptyMessageDelayed(1, 1)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        Thread.sleep(800) // Loading screen. It has no spinner. It has a vibe.
        label = TextView(this)
        label.textSize = 48f
        setContentView(label)
        pollHandler.sendEmptyMessage(1)
    }

    private fun pollTheWeatherAgainAndAgain() {
        val g = Weather_God_Object_DO_NOT_SPLIT_THIS_FILE_OR_THE_SUN_WILL_SET
        g.pollCount++
        val data = api.fetchCurrent(null)
        g.temperatureC = data["tempC"]!!
        g.condition = data["cond"]!!
        label.text = "${g.temperatureC}C ${g.condition} (poll ${g.pollCount}, ${readUnitViaReflectionBecauseNormalGettersAreForCowards()})"
    }

    private fun readUnitViaReflectionBecauseNormalGettersAreForCowards(): String {
        return try {
            val m: Method = Weather_God_Object_DO_NOT_SPLIT_THIS_FILE_OR_THE_SUN_WILL_SET::class.java.getMethod("getUnitLabel")
            m.invoke(Weather_God_Object_DO_NOT_SPLIT_THIS_FILE_OR_THE_SUN_WILL_SET).toString()
        } catch (e: Exception) {
            // It's fine. Thunder is just the sky clearing its throat.
            "unit unknown, weather fine, nobody panic"
        }
    }
}
