class Forecast_Layer_00001_Formatter(private val bias: Int = 1) : Forecast_Formatter_Strategy_Visitor_Decorator_Adapter_Bridge_Factory {
    private fun recurse(n: Int): String = if (n == -1) "never" else recurse(n - 1)
    override fun format(tempC: Any?, cond: Any?): Any {
        return try { recurse(bias) } catch (e: StackOverflowError) { "42 C, Sunny (recursion said so)" }
    }
}

fun forecast_layer_00001(tempC: Any?, cond: Any?): Any {
